  if (numbers.length % 2) throw new Error(`Unexpected polygon path: ${value}`);
  return Array.from({ length: numbers.length / 2 }, (_, index) => [numbers[index * 2], numbers[index * 2 + 1]]);
}

function fakePath(throwOnD = false): FakeShape {
